tool_input.old_string:
@reference "../../app/globals.css";

.overlay {
  @apply fixed inset-0 flex items-center justify-center bg-black/50 z-50;
}

.container {
  @apply bg-light rounded-lg shadow-lg p-6 max-w-sm w-full mx-4 flex flex-col gap-4;
}

.message {
  @apply text-base font-medium text-success text-center;
}

.button {
  @apply btn bg-success text-light hover:bg-success/90;
}

tool_input.new_string:
@reference "../../app/globals.css";

.overlay {
  @apply fixed inset-0 flex items-center justify-center bg-black/50 z-50;
}

.container {
  @apply bg-light rounded-lg shadow-lg p-6 max-w-sm w-full mx-4 flex flex-col gap-4;
}

.message {
  @apply text-base font-medium text-success text-center;
}

.button {
  @apply px-6 py-3 rounded-2xl font-medium transition-all duration-200 flex items-center justify-center;
  background: linear-gradient(135deg, var(--color-success) 0%, var(--color-success) 100%);
  color: white;
  box-shadow: 0 8px 24px rgba(5, 223, 114, 0.4);
}

.button:hover {
  opacity: 0.95;
  transform: translateY(-2px);
  box-shadow: 0 12px 32px rgba(5, 223, 114, 0.5);
}

.button:active {
  transform: translateY(0);
}

